{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a long-chain ester prodrug of a polar drug, had only 15% oral bioavailability in humans, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a lipophilic ester prodrug, showed 85 ± 15% absolute oral bioavailability in children, indicating that lipophilic ester prodrugs can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Perindopril, an ester prodrug, had 66% absolute oral bioavailability in humans, supporting high oral absorption for ester prodrugs.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "Capecitabine, an orally administered carbamate prodrug, has almost 100% oral bioavailability in humans.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is orlistat, a beta-lactone lipase inhibitor designed to act locally in the gastrointestinal tract; its established oral bioavailability is negligible and far below 20%, so the prediction is low despite several high-bioavailability ester prodrug analogs.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for orlistat is present in the supplied evidence.",
    "The closest low-F analog, laninamivir octanoate, has a different mechanism and therapeutic target.",
    "Most high-F analogs are absorbed prodrugs of nucleosides, ACE inhibitors, or antibiotics and are not structurally close to the beta-lactone lipase inhibitor scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

